#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint8_t data = 0x01, reg = 0;
    for (int i = 7; i >= 0; i--) {
        uint8_t bit = (data >> i) & 1;
        reg = (uint8_t)((reg << 1) | bit);
    }
    printf("0x%02X", reg);
}

